INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(29001, 'Hebrews 10:1', 'Hebrews', 10, 1, '&nbsp;ځکه چې شريعت صرف د راتلونکو ښو څيزونو سورے دے او د هغه حقيقى څيزونو اصلى شکل نۀ دے، او کومې قربانۍ چې هر کال بې‌ناغې کولے شى دا کله هم هغه خلق کاملولے نۀ شى څوک چې د خُدائ پاک عبادت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29002, 'Hebrews 10:2', 'Hebrews', 10, 2, '&nbsp;کۀ چرې هغوئ مکمل پاکوالے ورکولے شو، نو دا قربانۍ به ختمې شوې وې او عبادت کوونکى به يو ځل د تل دپاره پاک شوى وُو نو بيا به هغوئ خپل ځان ګناه ګار نۀ ګڼلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29003, 'Hebrews 10:3', 'Hebrews', 10, 3, '&nbsp;بلکې دا قربانيانې هر کال ګناهونه رايادوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29004, 'Hebrews 10:4', 'Hebrews', 10, 4, '&nbsp;ځکه چې دا ممکنه نۀ ده چې د غوَيانو او چېلو وينه ګناهونه لرې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29005, 'Hebrews 10:5', 'Hebrews', 10, 5, '&nbsp;ځکه خو کله چې مسيح دُنيا ته راغلو نو هغۀ وفرمائيل چې، ”تا قربانى او نذرانه خوښه نۀ کړه بلکې تا زما دپاره يو بدن تيار کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29006, 'Hebrews 10:6', 'Hebrews', 10, 6, '&nbsp;په سوزېدلې نذرانه او د ګناه په نذرانه تۀ خوشحاله نۀ وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29007, 'Hebrews 10:7', 'Hebrews', 10, 7, '&nbsp;بيا ما وفرمائيل، وګوره خُدايه پاکه، زۀ راغلم چې ستا مرضى پوره کړم، اے خُدايه پاکه، د کِتاب مقدس په پاڼو کښې يې زما په حقله دا ليکلى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29008, 'Hebrews 10:8', 'Hebrews', 10, 8, '&nbsp;مسيح اول وفرمائيل چې، ”نۀ خو تا قربانى او نذرونه او پوره سوزېدونکې نذرانې او د ګناه نذرانې خوښې کړې او نۀ په هغې خوشحاله شوے وې“ کۀ څۀ هم چې دا قربانۍ د شريعت په مطابق پېش کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29009, 'Hebrews 10:9', 'Hebrews', 10, 9, '&nbsp;او بيا هغۀ دا وفرمائيل چې، ”وګوره، زۀ راغلم چې ستا مرضى پوره کړم.“ هغه اولنۍ قربانى ځکه منسوخ کوى چې دوېمه قربانى هغه ځائ ونيسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29010, 'Hebrews 10:10', 'Hebrews', 10, 10, '&nbsp;او د خُدائ پاک د مرضۍ په وسيله مونږ د عيسىٰ مسيح د بدن د يو ځل قربانېدو په وجه د همېشه دپاره پاک کړے شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29011, 'Hebrews 10:11', 'Hebrews', 10, 11, '&nbsp;او هر يو اِمام روزانه د هغۀ خدمت کښې ولاړ وى او هم هغه يو رنګ قربانۍ بيا بيا پېش کوى کومې چې هيڅکله هم ګناهونه نۀ شى ختمولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29012, 'Hebrews 10:12', 'Hebrews', 10, 12, '&nbsp;خو کله چې مسيح د همېشه دپاره د ګناهونو د ختمولو دپاره يوه قربانى ورکړه نو بيا هغه د خُدائ پاک ښى لاس ته کښېناستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29013, 'Hebrews 10:13', 'Hebrews', 10, 13, '&nbsp;او د هغه وخت نه په دې انتظار دے چې د هغۀ دشمنان د هغۀ د پښو د لاندې کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29014, 'Hebrews 10:14', 'Hebrews', 10, 14, '&nbsp;ځکه چې هغه د يوې قربانۍ ورکولو په وسيله هغوئ د همېشه دپاره کامِل کړل څوک چې پاک کړے شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29015, 'Hebrews 10:15', 'Hebrews', 10, 15, '&nbsp;او روحُ القُدس هم مونږ ته دغه ګواهى راکوى ځکه چې هغه فرمائى چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29016, 'Hebrews 10:16', 'Hebrews', 10, 16, '&nbsp;”خو دا هغه نوے لوظ دے کوم به چې زۀ پس د دې نه د بنى اِسرائيلو د قبيلې سره وکړم، زۀ به خپل شريعت د هغوئ په مازغو کښې واچوم او د هغوئ په زړونو باندې به يې وليکم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29017, 'Hebrews 10:17', 'Hebrews', 10, 17, '&nbsp;او بيا دا هم فرمائى چې، ”زۀ به د هغوئ ګناهونه او بې‌شرعې کارونه نور بيا کله هم ياد نۀ کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29018, 'Hebrews 10:18', 'Hebrews', 10, 18, '&nbsp;او چې د هغوئ معافى شوې ده نو بيا نور د ګناهونو دپاره د قربانۍ پېش کولو حاجت نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29019, 'Hebrews 10:19', 'Hebrews', 10, 19, '&nbsp;نو په دې وجه اے وروڼو او خوېندو، مونږ د عيسىٰ د وينې په سبب زيات مقدس ځائ ته په اطمينان سره ورننوځو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29020, 'Hebrews 10:20', 'Hebrews', 10, 20, '&nbsp;هغۀ د خپل مرګ په وسيله د ژوندون دپاره يوه نوې لار د پړدې د مينځ نه کولاو کړه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29021, 'Hebrews 10:21', 'Hebrews', 10, 21, '&nbsp;نو ځکه چې مونږ سره لوئ اِمام دے څوک چې د خُدائ پاک د کور مختيار دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29022, 'Hebrews 10:22', 'Hebrews', 10, 22, '&nbsp;نو راځئ چې د زړۀ د اخلاصه او په پوره باور سره د خُدائ پاک په حضور کښې داخل شُو. ځکه چې زمونږ په ګناه ګار ضمير د مسيح وينه نوستلے شوې ده چې مونږ پاک کړى، او زمونږ بدن په پاکو اوبو سره وينځلے شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29023, 'Hebrews 10:23', 'Hebrews', 10, 23, '&nbsp;راځئ چې مونږ د خپل اُميد په اقرار کولو بغېر د يرېدو نه کلک ودرېږو ځکه چا چې لوظ کړے دے هغه وفادار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29024, 'Hebrews 10:24', 'Hebrews', 10, 24, '&nbsp;او راځئ چې سوچ وکړُو چې څنګه يو بل ته د مينې او نېکو کارونو د کولو ترغيب ورکوو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29025, 'Hebrews 10:25', 'Hebrews', 10, 25, '&nbsp;او چې مونږ په خپلو کښې د جماعت د راټولېدو نه منع نۀ شُو څنګه چې د ځينو خلقو عادت دے، بلکې يو بل له ډاډګيرنه ورکړئ، او څنګه چې تاسو د مالِک ورځ په رانزدې کېدو وينئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29026, 'Hebrews 10:26', 'Hebrews', 10, 26, '&nbsp;کۀ چرې مونږ د حق د پېژندلو نه پس هم قصداً ګناهونه کوُو نو بيا زمونږ د ګناهونو دپاره د يوې قربانۍ هم څۀ فائده نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29027, 'Hebrews 10:27', 'Hebrews', 10, 27, '&nbsp;خو يو يروونکے عدالت او غضبناک اور پاتې دے چې د خُدائ پاک مخالفين به وسوزوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29028, 'Hebrews 10:28', 'Hebrews', 10, 28, '&nbsp;هر څوک هم چې د موسىٰ شريعت نۀ منى هغه به د دوو يا درېو ګواهانو په ګواهۍ بغېر د څۀ رحم نه هلاک کړے شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29029, 'Hebrews 10:29', 'Hebrews', 10, 29, '&nbsp;نو تاسو سوچ وکړئ چې هغوئ به د څومره زياتې سزا لائق وګرځى چا چې د خُدائ پاک زوئ سپک ګڼلے وى، او د لوظ وينه چې هغوئ پرې پاک شوى وُو د هغې بې‌حرمتى کړى وى، او د فضل د روح بې‌عزتى يې کړى وى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29030, 'Hebrews 10:30', 'Hebrews', 10, 30, '&nbsp;ځکه چې مونږ هغه پېژنو چا چې فرمائيلى دى چې، ”بدل اخستل زما کار دے، بدل به زۀ اخلم،“ او بيا دا چې، ”مالِک به د خپل اُمت عدالت کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29031, 'Hebrews 10:31', 'Hebrews', 10, 31, '&nbsp;د ژوندى خُدائ پاک په لاسونو کښې ورتلل ډېره هيبتناکه خبره ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29032, 'Hebrews 10:32', 'Hebrews', 10, 32, '&nbsp;خو هغه اولنۍ ورځې رايادې کړئ کله چې د خُدائ پاک نُور په تاسو وځلېدو، نو تاسو په سخت وخت کښې مصيبتونه وزغمل او قائم پاتې شوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29033, 'Hebrews 10:33', 'Hebrews', 10, 33, '&nbsp;تاسو په څو څو کرَته بې‌عزته او د مصيبتونو په وجه د خلقو تماشه شوئ، او کله کله تاسو د هغوئ په بد سلوکۍ کښې هم مدد وکړو چا چې دا مصيبتونه زغمل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29034, 'Hebrews 10:34', 'Hebrews', 10, 34, '&nbsp;د قېديانو سره تاسو همدردى وکړه، او تاسو د خپل مال لوټ کېدل په خوشحالۍ سره منظور کړل، ځکه چې تاسو په دې پوهه وئ چې تاسو سره يو بهتر او د تل ميراث دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29035, 'Hebrews 10:35', 'Hebrews', 10, 35, '&nbsp;نو په دې وجه خپله زړۀ ورتيا مۀ پرېږدئ ځکه چې د دې ډېر اجر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29036, 'Hebrews 10:36', 'Hebrews', 10, 36, '&nbsp;نو تاسو ته د صبر ضرورت دے نو چې کله تاسو د خُدائ پاک مرضى پوره کړئ نو تاسو به دا لوظ کړے شوى څيزونه حاصل کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29037, 'Hebrews 10:37', 'Hebrews', 10, 37, '&nbsp;ځکه، ”اوس ډېر لږ وخت دے چې څوک چې راتلونکے دے هغه به راشى او ايسار به نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29038, 'Hebrews 10:38', 'Hebrews', 10, 38, '&nbsp;څوک چې صادق وى هغه به په ايمان پائى. او زما زړۀ د هغوئ نه خوشحاله نۀ دے څوک چې د ايمان نه وروستو کيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29039, 'Hebrews 10:39', 'Hebrews', 10, 39, '&nbsp;خو مونږ هغه خلق نۀ يُو څوک چې ايمان نه وروستو شى او بيا هلاک شى، خو مونږ وفادار خلق يُو څوک چې به بچ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29040, 'Hebrews 11:1', 'Hebrews', 11, 1, '&nbsp;نو ايمان دا دے چې په هغه څيزونو باور وکړُو چې د کوم په اُميد يُو، او په ناليدلو څيزونو يقين وکړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29041, 'Hebrews 11:2', 'Hebrews', 11, 2, '&nbsp;په حقيقت کښې زمونږ مشرانو د ايمان په وسيله د خُدائ پاک قبوليت حاصل کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29042, 'Hebrews 11:3', 'Hebrews', 11, 3, '&nbsp;د ايمان په وسيله مونږ ته پته ده چې عالمونه د خُدائ پاک په کلام جوړ شوى دى، نو چې څۀ په نظر راځى هغه د هغه څيزونو نه جوړ شوى دى کوم چې په نظر نۀ ښکارى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29043, 'Hebrews 11:4', 'Hebrews', 11, 4, '&nbsp;د ايمان په وسيله د خُدائ پاک دپاره هابيل د قائِن نه بهتره قربانى پېش کړه، او هم د دې په وسيله هغه د صادق په توګه منظور شو، او خُدائ پاک په خپله د هغۀ قربانى قبوله کړه، هغه مړ هم شو، خو د خپل ايمان په وسيله هغۀ زمونږ دپاره يو مثال پېش کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29044, 'Hebrews 11:5', 'Hebrews', 11, 5, '&nbsp;د ايمان په وسيله حنوک مړ نۀ شو بلکې آسمان ته ژوندے پورته کړے شو. هغه هيچا ونۀ موندلو ځکه چې خُدائ پاک هغه بره اوچت کړے وو، ځکه چې د هغۀ د پورته کېدو نه مخکښې دا ګواهى ورکړے شوه چې د هغۀ نه خُدائ پاک راضى دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29045, 'Hebrews 11:6', 'Hebrews', 11, 6, '&nbsp;او بغېر د ايمان نه د خُدائ پاک خوشحالول ناممکن دى، ځکه چې څوک خُدائ پاک ته راځى هغوئ ته په دې ايمان راوړل په کار دى چې هغه موجود دے او چې څوک هغه لټوى، هغوئ ته اجر ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29046, 'Hebrews 11:7', 'Hebrews', 11, 7, '&nbsp;د ايمان په وسيله نوح د هغه څيزونو په باب کښې چې تر هغه وخته په نظر نۀ راتلل، هدايت وموندو او د خپل خاندان د بچ کولو دپاره يې کِشتۍ جوړه کړه. هغۀ د خپل ايمان په وسيله ټوله دُنيا مجرمه کړه او د هغه صداقت وارث شو چې د ايمان په سبب وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29047, 'Hebrews 11:8', 'Hebrews', 11, 8, '&nbsp;د ايمان په وسيله کله چې اِبراهيم وبللے شو نو هغه حُکم يې ومنلو او هغه ځائ ته لاړو کوم چې هغۀ ته په ميراث کښې ملاوېدونکے وو، او ورته دا پته نۀ وه چې چرته روان دے خو بيا هم د خپل مُلک نه روان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29048, 'Hebrews 11:9', 'Hebrews', 11, 9, '&nbsp;او د ايمان په وسيله په هغه مُلک کښې د مسافرو په شان دېره شو د کوم چې ورسره لوظ شوے وو، او سره د اِسحاق او يعقوب چې هغوئ هم په هغه لوظ وارثان وُو، په خېمو کښې اوسېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29049, 'Hebrews 11:10', 'Hebrews', 11, 10, '&nbsp;ځکه چې اِبراهيم د هغه مضبوط ښار ليدو اُميد ساتلو چې د منصوبې ماهر او جوړوونکے يې خُدائ پاک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29050, 'Hebrews 11:11', 'Hebrews', 11, 11, '&nbsp;هم د ايمان په وسيله ساره د ماشوم پېدا کولو طاقت وموندو، اګر کۀ هغه ډېره بوډۍ او شنډه هم وه خو د هغې دا ايمان وو چې خُدائ پاک به خپل لوظ پوره کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29051, 'Hebrews 11:12', 'Hebrews', 11, 12, '&nbsp;نو په دې وجه بيا د يو سړى نه چې د مړى په شان وو، چې په آسمان کښې څومره ستورى دى او چې د سمندر په غاړه څومره شګې دى بې‌شمېره اولاد پېدا شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29052, 'Hebrews 11:13', 'Hebrews', 11, 13, '&nbsp;هغه ټول خلق مړۀ شول د چا چې تر مرګ پورې د خُدائ پاک په ورکړے شوى لوظ ايمان وو. هغوئ ته هغه څۀ مِلاو نۀ شو د کوم څيز چې لوظ شوے وو خو هغوئ د لرې نه دا وليدو او ورته خوشحاله شول. هغوئ دا خبره قبوله کړه چې په زمکه هغوئ مسافر او غېر مُلکيان وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29053, 'Hebrews 11:14', 'Hebrews', 11, 14, '&nbsp;ځکه چې کوم خلق دغه شان خبرې کوى، د هغوئ نه د دې خبرې پته لګى چې هغوئ د خپل مُلک په تلاش کښې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29054, 'Hebrews 11:15', 'Hebrews', 11, 15, '&nbsp;کۀ هغوئ د هغه مُلک ارمان کولو د کوم نه چې هغوئ راوتلى وُو، نو هغوئ ته د واپس تللو موقع وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29055, 'Hebrews 11:16', 'Hebrews', 11, 16, '&nbsp;خو په حقيقت کښې هغوئ د يو بهتر ځائ، يعنې د آسمانى مُلک په تلاش کښې وُو، نو ځکه خُدائ پاک په دې نۀ شرميږى چې د هغوئ خُدائ پاک دې وبللے شى، نو هغۀ هغوئ له يو ښار تيار کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29056, 'Hebrews 11:17', 'Hebrews', 11, 17, '&nbsp;هم د ايمان په وسيله اِبراهيم د آزمېښت په وخت اِسحاق د قربانۍ په توګه پېش کړو. اِبراهيم چا سره چې خُدائ پاک لوظونه کړى وُو هغه دې ته تيار شو چې خپل يکى يو زوئ قربان کړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29057, 'Hebrews 11:18', 'Hebrews', 11, 18, '&nbsp;کۀ څۀ هم چې خُدائ پاک فرمائيلى وُو، ”چې هم د اِسحاق نه به ستا نسل قائم وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29058, 'Hebrews 11:19', 'Hebrews', 11, 19, '&nbsp;ځکه چې د اِبراهيم په دې ايمان وو چې خُدائ پاک د مړو نه د بيا ژوندى کېدلو قدرت لرى، نو څنګه چې هغۀ وئيل نو هم هغسې يې هغه د مړو نه بيا ژوندے وموندلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29059, 'Hebrews 11:20', 'Hebrews', 11, 20, '&nbsp;هم د ايمان په وسيله اِسحاق يعقوب او عِيسو دواړو ته د مستقبل برکت ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29060, 'Hebrews 11:21', 'Hebrews', 11, 21, '&nbsp;هم د ايمان په وسيله يعقوب چې کله مړ کېدو د يوسف وړو زامنو ته يې برکت ورکړو او د خپلې امسا په سر يې د تکيه کولو سره سجده وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29061, 'Hebrews 11:22', 'Hebrews', 11, 22, '&nbsp;هم د ايمان په وسيله کله چې د يوسف مرګ نزدې شو نو د بنى اِسرائيلو د مِصر نه د وتلو هدايت يې وکړو او د خپلو هډُوکو د ښخولو په حقله يې حُکم ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29062, 'Hebrews 11:23', 'Hebrews', 11, 23, '&nbsp;هم د ايمان په وسيله د موسىٰ مور پلار د هغۀ د پېدايښت نه پس تر درېو مياشتو پورې هغه پټ وساتلو ځکه چې هغوئ وليدل چې ماشوم ښکلے دے او هغوئ د بادشاه د حُکم نه ونۀ يرېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29063, 'Hebrews 11:24', 'Hebrews', 11, 24, '&nbsp;د ايمان په وسيله موسىٰ چې کله لوئ شو نو د فِرعون د لور د زوئ بللو نه يې اِنکار وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29064, 'Hebrews 11:25', 'Hebrews', 11, 25, '&nbsp;هغۀ د عارضى ژوندون د يو څو ورځو عېش عشرت او ګناه په ځائ د خُدائ پاک د اُمت سره د بد سلوک زغمل زيات خوښ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29065, 'Hebrews 11:26', 'Hebrews', 11, 26, '&nbsp;هغۀ د مسيح دپاره بد سلوک زغمل د مِصر د خزانو نه لوئ دولت وګڼلو ځکه چې د هغۀ نظر په لوئ اجر حاصلولو وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29066, 'Hebrews 11:27', 'Hebrews', 11, 27, '&nbsp;هم د ايمان په وسيله موسىٰ مِصر پرېښودو او د بادشاه د قهر نه ونۀ يرېدو، او خپل سفر يې جارى وساتلو ځکه چې د هغۀ نظر په ناليدلى خُدائ پاک باندې وو او پرې قائم پاتې شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29067, 'Hebrews 11:28', 'Hebrews', 11, 28, '&nbsp;هم د ايمان په وسيله موسىٰ بنى اِسرائيلو ته د فسح اختر کولو حکم وکړو او د دروازو په دُرشلونو باندې يې په وينه نوستلو عمل وکړو د دې دپاره چې د مرګ فرښته د دوئ اول پېدا شوى زامن هلاک نۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29068, 'Hebrews 11:29', 'Hebrews', 11, 29, '&nbsp;او د ايمان په وسيله بنى اِسرائيل په بحرِقُلزم داسې پورې وتل لکه چې په وُچه زمکه، خو کله چې مِصريانو د پورې وتو کوشش وکړو نو غرق شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29069, 'Hebrews 11:30', 'Hebrews', 11, 30, '&nbsp;هم د ايمان په وسيله د يريحو ښار دېوالونه د بنى اِسرائيلو تر اوو ورځو پورې ګېرچاپېره تاوېدلو نه پس راونړېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29070, 'Hebrews 11:31', 'Hebrews', 11, 31, '&nbsp;هم د ايمان په وسيله راحب کنجره د نافرمانو سره هلاکه نۀ شوه ځکه چې هغې اِسرائيلى جاسوسان په خير قبول کړى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29071, 'Hebrews 11:32', 'Hebrews', 11, 32, '&nbsp;او نور زۀ څۀ ووايم؟ ځکه دومره وخت راسره نشته چې د جدعون، برق، سمسون، جفتاه، داؤد، سموئيل او د نورو نبيانو حال بيان کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29072, 'Hebrews 11:33', 'Hebrews', 11, 33, '&nbsp;هغوئ د ايمان په وسيله بادشاهۍ فتح کړې، د عدل او اِنصاف حکومت يې قائم کړو او هغه لوظونه چې خُدائ پاک کړى وُو وې موندل، د زمرو خولې يې بندې کړې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29073, 'Hebrews 11:34', 'Hebrews', 11, 34, '&nbsp;د اور تاو يې بند کړو، او د تُورې د مخ نه بچ شول. هغوئ په کمزورتيا کښې طاقت حاصل کړو، په جنګ کښې طاقتور شول او د غېرو مُلکونو فوجونه يې په تېښته کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29074, 'Hebrews 11:35', 'Hebrews', 11, 35, '&nbsp;ښځو خپل مړى بيا ژوندى وموندل. ځينو په ځان وهل ټکول تير کړل، رهائى يې منظوره نۀ کړه، د دې دپاره چې هغوئ ته بهتر قيامت حاصل شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29075, 'Hebrews 11:36', 'Hebrews', 11, 36, '&nbsp;په ځينو پورې يې ټوقې وکړې، په کوړو يې ووهل، او څۀ يې په زنځيرونو وتړل او په قېد کښې يې واچول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29076, 'Hebrews 11:37', 'Hebrews', 11, 37, '&nbsp;ځينې يې سنګسار کړل، او په اره يې وڅيرل، په تُورو يې مړۀ کړل، د ګډو بيزو څرمنې يې اغوستې وې، په محتاجۍ، په مصيبت، د بد سلوکۍ په حالت کښې سروهلى بروهلى ګرځېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29077, 'Hebrews 11:38', 'Hebrews', 11, 38, '&nbsp;دُنيا د هغوئ لائقه نۀ وه، هغوئ په دشتو، غرونو او د زمکې په غارونو او سوړو کښې هواګير وګرځېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29078, 'Hebrews 11:39', 'Hebrews', 11, 39, '&nbsp;د خپل ايمان په وجه د هغوئ ټولو ښۀ تعريف وشو، خو هغه څۀ ورته مِلاو نۀ شول د کوم چې ورسره لوظ شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29079, 'Hebrews 11:40', 'Hebrews', 11, 40, '&nbsp;نو خُدائ پاک زمونږ دپاره يوه ښۀ منصوبه جوړه کړې وه، هغه دا چې زمونږ سره به هغوئ کامِل کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29080, 'Hebrews 12:1', 'Hebrews', 12, 1, '&nbsp;نو په دې وجه بيا چې د ګواهانو دومره لويه ګڼه زمونږ نه چاپېره ده نو راځئ چې مونږ هم هر يو پيټے او هغه ګناه چې مونږ په آسانۍ سره انښلوى د ځان نه لرې کړُو، او راځئ چې په هغه منډه کښې په صبر سره وزغلو چې مونږ له مقرر ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29081, 'Hebrews 12:2', 'Hebrews', 12, 2, '&nbsp;او عيسىٰ چې د ايمان بانى او کاملونکے دے هغۀ ته وګورو چا چې د خوشحالۍ حاصلولو دپاره د سولۍ مرګ وزغملو او د دې په بې‌عزتۍ ونۀ شرمېدلو او د خُدائ پاک د تخت په ښى لاس کښېناستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29082, 'Hebrews 12:3', 'Hebrews', 12, 3, '&nbsp;په هغه چا غور وکړئ چا چې د ګناهګارانو خلقو دومره مخالفت وزغملو، نو چې تاسو ستړى او بې‌همته نۀ شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29083, 'Hebrews 12:4', 'Hebrews', 12, 4, '&nbsp;ستاسو د ګناه خلاف جنګ کښې تاسو لا تر اوسه دې حد پورې نۀ يئ رسېدلى چې په کښې ستاسو وينه تويه شوى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29084, 'Hebrews 12:5', 'Hebrews', 12, 5, '&nbsp;او تاسو هغه نصيحت هېر کړے دے چې تاسو له د زامنو په شان په دې ټکو درکړے شو چې، ”زما زويه، د مالِک تنبيه سپکه مۀ ګڼه، چې هر کله چې هغه تا ملامتوى، نو بې‌زړۀ کېږه مه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29085, 'Hebrews 12:6', 'Hebrews', 12, 6, '&nbsp;ځکه چا سره چې مالِک خُدائ مينه کوى نو د هغۀ تنبيه هم کوى. او هغه هر هغه چا له سزا هم ورکوى چې هغه يې د خپل زوئ په توګه قبول کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29086, 'Hebrews 12:7', 'Hebrews', 12, 7, '&nbsp;تاسو تنبيه وزغمئ، خُدائ پاک تاسو سره د زامنو په شان سلوک کوى. پلار د هر يو زوئ تنبيه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29087, 'Hebrews 12:8', 'Hebrews', 12, 8, '&nbsp;او کۀ تاسو له هغه تنبيه درنۀ کړے شى په کومه کښې چې ټول بچى شريک دى نو تاسو حراميان شوئ، نه چې زامن.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29088, 'Hebrews 12:9', 'Hebrews', 12, 9, '&nbsp;د دې نه علاوه زمونږ انسانى پلاران څوک چې مونږ تنبيه کوى نو په دې وجه مونږ د هغوئ عزت کوُو. نو مونږ به د دې نه څومره زياته د هغه چا تابعدارى کوُو څوک چې زمونږ روحانى پلار دے او مونږ له ژوند راکوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29089, 'Hebrews 12:10', 'Hebrews', 12, 10, '&nbsp;هغوئ خو د لږ وخت دپاره د خپلې پوهې په مطابق زمونږ تنبيه کوى، خو د خُدائ پاک تنبيه کول زمونږ د فائدې دپاره دى ترڅو چې مونږ د هغۀ په پاکوالى کښې شامل شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29090, 'Hebrews 12:11', 'Hebrews', 12, 11, '&nbsp;همېشه په تنبيه کولو کښې مزه نۀ وى بلکې هغه دردناک وى. خو وروستو دا د هغوئ دپاره د صداقت او امن مېوه ونيسى د چا چې تنبيه شوى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29091, 'Hebrews 12:12', 'Hebrews', 12, 12, '&nbsp;نو په دې وجه خپل کمزورى لاسونه او پښې مضبوطې کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29092, 'Hebrews 12:13', 'Hebrews', 12, 13, '&nbsp;د خپلو پښو دپاره نېغې لارې خوښې کړئ ځکه څوک چې شل ګوډ دى چې هغوئ درز ونۀ خورى بلکې مضبوط شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29093, 'Hebrews 12:14', 'Hebrews', 12, 14, '&nbsp;ټولو سره د صُلح کوشش کوئ او د هغې پاکيزګۍ طلبګار اوسئ د کومې نه بغېر چې به هيڅوک مالِک ونۀ وينى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29094, 'Hebrews 12:15', 'Hebrews', 12, 15, '&nbsp;خو دې ته ګورئ چې څوک د خُدائ پاک د فضل نه پاتې نۀ شى، او هسې نه چې چرته زهريله جرړه راونۀ ټوکيږى او ستاسو دپاره د عذاب سبب شى او د هغې په سبب ډېر خلق پليت شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29095, 'Hebrews 12:16', 'Hebrews', 12, 16, '&nbsp;او د دې خبرې خيال ساتئ چې په تاسو کښې څوک د عِيسو په شان زناکار او بې‌دينه نۀ شى چا چې د يو وخت د روټۍ په بدل کښې د خپلې مشرۍ حق خرڅ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29096, 'Hebrews 12:17', 'Hebrews', 12, 17, '&nbsp;نو تاسو ته پته ده چې کله بيا هغۀ وروستو د برکت وارث کېدل غوښتل نو هغه نامنظور شو. او هغۀ ته د توبې ويستلو موقع مِلاو نۀ شوه سره د دې چې هغۀ په وير ژړا په هغه برکت پسې ډېر لټون وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29097, 'Hebrews 12:18', 'Hebrews', 12, 18, '&nbsp;نو تاسو هغه غر ته نۀ يئ راغلى چې به د اور شغلو، تيارې، تورتم او طوفان راګېرولو، لکه څنګه چې بنى اِسرائيل د سينا غرۀ ته راغلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29098, 'Hebrews 12:19', 'Hebrews', 12, 19, '&nbsp;او کله چې د بيګل آواز او کلام خلقو واورېدو نو هغوئ مِنت وکړو چې مونږ سره دې نور کلام ونۀ کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29099, 'Hebrews 12:20', 'Hebrews', 12, 20, '&nbsp;نو هغوئ دا حُکم برداشت نۀ کړے شو چې، ”کۀ يو ځناور هم د دې غر سره ولګى نو هغه دې په کاڼو مړ کړے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29100, 'Hebrews 12:21', 'Hebrews', 12, 21, '&nbsp;هغه منظر په رښتيا سره داسې هيبتناک وو چې موسىٰ وفرمائيل چې، ”زۀ د يرې نه ډېر رپېږم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');